        const simple = this.quietEmit(() => this.emitStringPtrLen(part, locals));
        if (simple !== "(i32.const 0) (i32.const 0)") {
          const [pW, lW] = splitTwoWatExprs(simple);
          concatAppend(pW, lW);
          return;
        }
