        // know: an f64 `g(2.5, 4)` went to the i32 printer (ld98, found with ld78, 2026-10-22).
        if (wat.trimStart().startsWith("(call_indirect")) {
          const have = this.watResultType(wat, l);
          if (have === "f64" || have === "i64") return { wat, type: have };
        }
